1	//! Rate-limit and credits display shaping for status surfaces.
2	//!
3	//! This module maps `RateLimitSnapshot` protocol payloads into display-oriented rows that the TUI
4	//! can render in `/status` and status-line contexts without duplicating formatting logic.
5	//!
6	//! The key contract is that time-sensitive values are interpreted relative to a caller-provided
7	//! capture timestamp so stale detection and reset labels remain coherent for a given draw cycle.
8	use crate::chatwidget::get_limits_duration;
9	use crate::text_formatting::capitalize_first;
10	
11	use super::helpers::format_reset_timestamp;
12	use chrono::DateTime;
13	use chrono::Duration as ChronoDuration;
14	use chrono::Local;
15	use chrono::Utc;
16	use codex_protocol::protocol::CreditsSnapshot as CoreCreditsSnapshot;
17	use codex_protocol::protocol::RateLimitSnapshot;
18	use codex_protocol::protocol::RateLimitWindow;
19	
20	const STATUS_LIMIT_BAR_SEGMENTS: usize = 20;
21	const STATUS_LIMIT_BAR_FILLED: &str = "█";
22	const STATUS_LIMIT_BAR_EMPTY: &str = "░";
23	
24	#[derive(Debug, Clone)]
25	pub(crate) struct StatusRateLimitRow {
26	    /// Human-readable row label, such as `"5h limit"` or `"Credits"`.
27	    pub label: String,
28	    /// Value payload for the row.
29	    pub value: StatusRateLimitValue,
30	}
31	
32	/// Display value variants for a single rate-limit row.
33	#[derive(Debug, Clone)]
34	pub(crate) enum StatusRateLimitValue {
35	    /// Percent-based usage window with optional reset timestamp text.
36	    Window {
37	        /// Percent of the window that has been consumed.
38	        percent_used: f64,
39	        /// Localized reset string, or `None` when unknown.
40	        resets_at: Option<String>,
41	    },
42	    /// Plain text value used for non-window rows.
43	    Text(String),
44	}
45	
46	/// Availability state for rate-limit data shown in status output.
47	#[derive(Debug, Clone)]
48	pub(crate) enum StatusRateLimitData {
49	    /// Snapshot data is recent enough for normal rendering.
50	    Available(Vec<StatusRateLimitRow>),
51	    /// Snapshot data exists but is older than the staleness threshold.
52	    Stale(Vec<StatusRateLimitRow>),
53	    /// No snapshot data is currently available.
54	    Missing,
55	}
56	
57	/// Maximum age before a snapshot is considered stale in status output.
58	pub(crate) const RATE_LIMIT_STALE_THRESHOLD_MINUTES: i64 = 15;
59	
60	/// Display-friendly representation of one usage window from a snapshot.
61	#[derive(Debug, Clone)]
62	pub(crate) struct RateLimitWindowDisplay {
63	    /// Percent used for the window.
64	    pub used_percent: f64,
65	    /// Human-readable local reset time.
66	    pub resets_at: Option<String>,
67	    /// Window length in minutes when provided by the server.
68	    pub window_minutes: Option<i64>,
69	}
70	
71	impl RateLimitWindowDisplay {
72	    fn from_window(window: &RateLimitWindow, captured_at: DateTime<Local>) -> Self {
73	        let resets_at_utc = window
74	            .resets_at
75	            .and_then(|seconds| DateTime::<Utc>::from_timestamp(seconds, 0))
76	            .map(|dt| dt.with_timezone(&Local));
77	        let resets_at = resets_at_utc.map(|dt| format_reset_timestamp(dt, captured_at));
78	
79	        Self {
80	            used_percent: window.used_percent,
81	            resets_at,
82	            window_minutes: window.window_minutes,
83	        }
84	    }
85	}
86	
87	#[derive(Debug, Clone)]
88	pub(crate) struct RateLimitSnapshotDisplay {
89	    /// Canonical limit identifier (for example: `codex` or `codex_other`).
90	    pub limit_name: String,
91	    /// Local timestamp representing when this display snapshot was captured.
92	    pub captured_at: DateTime<Local>,
93	    /// Primary usage window (typically short duration).
94	    pub primary: Option<RateLimitWindowDisplay>,
95	    /// Secondary usage window (typically weekly).
96	    pub secondary: Option<RateLimitWindowDisplay>,
97	    /// Optional credits metadata when available.
98	    pub credits: Option<CreditsSnapshotDisplay>,
99	}
100	
101	/// Display-ready credits state extracted from protocol snapshots.
102	#[derive(Debug, Clone)]
103	pub(crate) struct CreditsSnapshotDisplay {
104	    /// Whether credits tracking is enabled for the account.
105	    pub has_credits: bool,
106	    /// Whether the account has unlimited credits.
107	    pub unlimited: bool,
108	    /// Raw balance text as provided by the backend.
109	    pub balance: Option<String>,
110	}
111	
112	/// Converts a protocol snapshot into UI-friendly display data.
113	///
114	/// Pass the timestamp from the same observation point as `snapshot`; supplying a significantly
115	/// older or newer `captured_at` can produce misleading reset labels and stale classification.
116	#[cfg(test)]
117	pub(crate) fn rate_limit_snapshot_display(
118	    snapshot: &RateLimitSnapshot,
119	    captured_at: DateTime<Local>,
120	) -> RateLimitSnapshotDisplay {
121	    rate_limit_snapshot_display_for_limit(snapshot, "codex".to_string(), captured_at)
122	}
123	
124	pub(crate) fn rate_limit_snapshot_display_for_limit(
125	    snapshot: &RateLimitSnapshot,
126	    limit_name: String,
127	    captured_at: DateTime<Local>,
128	) -> RateLimitSnapshotDisplay {
129	    RateLimitSnapshotDisplay {
130	        limit_name,
131	        captured_at,
132	        primary: snapshot
133	            .primary
134	            .as_ref()
135	            .map(|window| RateLimitWindowDisplay::from_window(window, captured_at)),
136	        secondary: snapshot
137	            .secondary
138	            .as_ref()
139	            .map(|window| RateLimitWindowDisplay::from_window(window, captured_at)),
140	        credits: snapshot.credits.as_ref().map(CreditsSnapshotDisplay::from),
141	    }
142	}
143	
144	impl From<&CoreCreditsSnapshot> for CreditsSnapshotDisplay {
145	    fn from(value: &CoreCreditsSnapshot) -> Self {
146	        Self {
147	            has_credits: value.has_credits,
148	            unlimited: value.unlimited,
149	            balance: value.balance.clone(),
150	        }
151	    }
152	}
153	
154	/// Builds display rows from a snapshot and marks stale data by capture age.
155	///
156	/// Callers should pass `Local::now()` for `now` at render time; using a cached timestamp can make
157	/// fresh data appear stale or prevent stale warnings from appearing.
158	pub(crate) fn compose_rate_limit_data(
159	    snapshot: Option<&RateLimitSnapshotDisplay>,
160	    now: DateTime<Local>,
161	) -> StatusRateLimitData {
162	    match snapshot {
163	        Some(snapshot) => compose_rate_limit_data_many(std::slice::from_ref(snapshot), now),
164	        None => StatusRateLimitData::Missing,
165	    }
166	}
167	
168	pub(crate) fn compose_rate_limit_data_many(
169	    snapshots: &[RateLimitSnapshotDisplay],
170	    now: DateTime<Local>,
171	) -> StatusRateLimitData {
172	    if snapshots.is_empty() {
173	        return StatusRateLimitData::Missing;
174	    }
